import{_ as n,o as a,c as e,ag as o}from"./chunks/framework.DUTPmUpA.js";const p="data:image/png;base64,",t="/_assets/vConsole.CF7P5zYM.png",l="/_assets/toolbar1.bFFKwb-a.png",A="/_assets/toolbar2.B2RghaWA.png",h=JSON.parse('{"title":"улучшение vConsole","description":"","frontmatter":{"title":"улучшение vConsole","author":"Kain","steamId":"76561198011709789","date":"01.04.2022"},"headers":[],"relativePath":"tools/improvement-vConsole.md","filePath":"tools/improvement-vConsole.md"}'),i={name:"tools/improvement-vConsole.md"};function r(c,s,u,m,b,d){return a(),e("div",null,[...s[0]||(s[0]=[o('<ul><li></li></ul><h1 id="улучшение-vconsole" tabindex="-1">улучшение vConsole <a class="header-anchor" href="#улучшение-vconsole" aria-label="Permalink to &quot;улучшение vConsole&quot;">​</a></h1><p><img src="'+p+'" alt="icon"></p><h2 id="vконсоль" tabindex="-1">vКонсоль <a class="header-anchor" href="#vконсоль" aria-label="Permalink to &quot;vКонсоль&quot;">​</a></h2><p>Dota2 Tools имеет консоль <code>vConsole2.exe</code>.</p><p>Сегодня я покажу вам, как изменить функционал панели инструментов. В этой статье мы не будем рассматривать настройку и стандартные возможности программы vConsole.</p><blockquote><p>Стандартный вид панели инструментов: <img src="'+t+`" alt="vconsole"></p></blockquote><p>Это та часть программы, которую мы сегодня продолжим. Какие возможности мы получим:</p><ol><li>Кнопка запускает инструмент из dll (в конфигурации по умолчанию — репортер ошибок и NetGraph).</li><li>Кнопка применяет консольную команду (в конфигурации по умолчанию запускает AssetBrowser).</li><li>Кнопка запускает внешнюю программу (VsCode, Notepad++, Sublime text и, конечно же, Dota2 Tools).</li></ol><p>В варианте 1 мы, вероятно, ничего не сможем изменить (или это будет очень сложно и моих знаний не хватает). Но двое других в самый раз.</p><p>Нам понадобится вот такой файл конфигурации для консоли: <code>dota 2 beta\\game\\core\\tools\\sdk_vconsole_subtools.txt</code></p><p>Формат файла — обычный ключ-значение. Ключевые параметры, которые мне удалось найти для этого файла:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>m_Name                       - Section name - importance is low, no visibility (but better to use).</span></span>
<span class="line"><span>m_MenuString                 - Name for menu list Tools.</span></span>
<span class="line"><span>m_SubToolIconPath            - Path for image icon (Button or menu). Great choice here &quot;\\dota 2 beta\\game\\core\\tools\\images\\&quot;. You can also shorten the way &quot;game:tools/images/workshopmanager/icon_refresh_activated.png&quot;</span></span>
<span class="line"><span>m_ToolbarString              - Name for button.</span></span>
<span class="line"><span>m_StatusBarTipString         - ToolTip in status bar and pop-up tooltip on the button.</span></span>
<span class="line"><span>m_CommandString              - any/all console commands that you already use in Dota2 Tools, (commands separated by semicolons are executed alternately, as in the console).</span></span>
<span class="line"><span>m_ExecutablePath             - the path to the executable file. (the slash in the path name, must be escaped with a slash \\\\)</span></span>
<span class="line"><span>m_ExecutableArguments        - arguments to run the executable file</span></span>
<span class="line"><span>m_LibraryPath                - the path to the DLL (for internal Dota tools)</span></span>
<span class="line"><span>m_AdditionalDependencies     - additional dependencies (probably expand the tools we are not really available)</span></span>
<span class="line"><span>m_bRequiresAppConnection     - Checking the connection to the application Dota2 (if Dota2 is running the icon takes full color, otherwise the icon is completely in shades of gray and cannot be clicked)</span></span>
<span class="line"><span>m_bRequiresToolConnection    - Checking the connection to the application Dota2 Tools (AssetBrowser only in tools, netgraph is also available in Dota2)</span></span>
<span class="line"><span>m_bInternalUseOnly           - only internal use - the essence is not clear.</span></span>
<span class="line"><span>m_bAllowAutoStart            - run at console start (not sure if it works in every situation)</span></span>
<span class="line"><span>m_ToolConfig                 - I don&#39;t know what it&#39;s for.(Maybe here you can specify the config from PET Hammer and other tools)</span></span>
<span class="line"><span>m_MaterialSystemDependencies - we are not interested (section with other dependencies - did not notice the difference by editing it)</span></span>
<span class="line"><span>m_SubTools                   - Our area for customization</span></span>
<span class="line"><span>// +dota_launch_custom_game  - comments work</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>Многие имена будут говорить сами за себя.</p><p>Нас интересует раздел <code>m_SubTools</code> этого файла.</p><p>::: предупреждение DOTA2 может перезаписать этот файл после обновления (не всегда), обязательно сделайте резервную копию (с вашими изменениями). :::</p><p>Примеры из моего конфига. перезапуск карты с очисткой консоли:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    m_Name                      = &quot;Restart&quot;</span></span>
<span class="line"><span>    m_MenuString                = &quot;Restart&quot;</span></span>
<span class="line"><span>    m_SubToolIconPath           = &quot;game:tools/images/workshopmanager/icon_refresh_activated.png&quot;</span></span>
<span class="line"><span>    m_ToolbarString             = &quot;Restart&quot;</span></span>
<span class="line"><span>    m_StatusBarTipString        = &quot;Restart map&quot;</span></span>
<span class="line"><span>    m_CommandString             = &quot;clear;restart&quot;</span></span>
<span class="line"><span>    m_bRequiresToolConnection   = true</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>запуск Dota2 Tools с тестовым аддоном и параметрами запуска:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    m_Name                      = &quot;tp&quot;</span></span>
<span class="line"><span>    m_MenuString                = &quot;Test project&quot;</span></span>
<span class="line"><span>    m_SubToolIconPath           = &quot;game:tools/images/hammer/toggle_tools_materials_activated.png&quot;</span></span>
<span class="line"><span>    m_ToolbarString             = &quot;Test A&quot;</span></span>
<span class="line"><span>    m_StatusBarTipString        = &quot;Test Addon load&quot;</span></span>
<span class="line"><span>    m_ExecutablePath            = &quot;X:\\\\Steam\\\\steamapps\\\\common\\\\dota 2 beta\\\\game\\\\bin\\\\win64\\\\dota2.exe&quot;</span></span>
<span class="line"><span>    m_ExecutableArguments       = &quot;-nobreakpad 375360 -tools -addon test -novid -uidev -dev -nominidumps -condebug -toconsole -vconsole &quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>запуск программы VSCode с аргументами (в данном случае указывается рабочая область):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>    m_Name                      = &quot;vsc&quot;</span></span>
<span class="line"><span>    m_MenuString                = &quot;VSCode&quot;</span></span>
<span class="line"><span>    m_SubToolIconPath           = &quot;C:/Microsoft VS Code/resources/app/resources/win32/code_70x70.png&quot;</span></span>
<span class="line"><span>    m_ToolbarString             = &quot;VSCode XX&quot;</span></span>
<span class="line"><span>    m_StatusBarTipString        = &quot;Run Vscode Addon XxxXxx&quot;</span></span>
<span class="line"><span>    m_ExecutablePath            = &quot;X:\\\\Microsoft VS Code\\\\Code.exe&quot;</span></span>
<span class="line"><span>    m_ExecutableArguments       = &quot;X:\\\\xxxx\\\\xx_scripts.code-workspace&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><hr><p>View of my toolbar without Dota2 tools running: <img src="`+l+'" alt="toolbar1"></p><p>with running tools:</p><p><img src="'+A+'" alt="toolbar2"></p><p>I hope my article will help you better organize your workspace when developing addons and you will be able to make more good and interesting projects.</p><blockquote><p>PS мои родные языки НА РУС, прошу прощения за возможные неточности перевода.</p></blockquote>',28)])])}const C=n(i,[["render",r]]);export{h as __pageData,C as default};
